SELECT schedule_date, SUM(day_plan_qty) as day_plan_qty, SUM(night_plan_qty) as night_plan_qty, SUM(next_day_plan_qty) as next_day_plan_qty, SUM(stock_qty) as stock_qty FROM t_cd90_schedule_result WHERE schedule_date = #{scheduleDate}
and INSTR(big_roll_code, #{bigRollCode,jdbcType=VARCHAR}) > 0
and INSTR(cloth_code, #{clothCode,jdbcType=VARCHAR}) > 0
and instr(concat(',',machine_id,','), concat(',',#{machineId},','))>0
and IS_RELEASE = #{isRelease}
